SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='a2213ead-91cc-5713-a2cc-ae82b1d361ca'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('73457ca4-16c9-5dbb-8d64-61869a0656a7','70e0abf4-d3db-550b-869e-752e1d9189ef')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='a2213ead-91cc-5713-a2cc-ae82b1d361ca'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='a2213ead-91cc-5713-a2cc-ae82b1d361ca'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('73457ca4-16c9-5dbb-8d64-61869a0656a7','70e0abf4-d3db-550b-869e-752e1d9189ef')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='a2213ead-91cc-5713-a2cc-ae82b1d361ca'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='73457ca4-16c9-5dbb-8d64-61869a0656a7' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-shared-identical-text-key' AND q.fingerprint='fc74b43b2249294f3e78d89fb97f37cabf8e154c93972d3c65d05c7c3e930128'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"unique-distinct-scope-b","status":"ok","value":{"customerProfileId":"a2213ead-91cc-5713-a2cc-ae82b1d361ca","userId":"6e8a95c3-3bea-5121-98e7-c96a68873b95","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"73457ca4-16c9-5dbb-8d64-61869a0656a7","semanticKey":"customer-controls-shared-identical-text-key","fingerprint":"fc74b43b2249294f3e78d89fb97f37cabf8e154c93972d3c65d05c7c3e930128","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='93a30fe9-ac60-52f2-9755-62ad1bd0cd96' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='bfde8c86-4a92-5ed8-90c9-8984f8272b89' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"a2213ead-91cc-5713-a2cc-ae82b1d361ca"},"prior":null,"committed":{"id":"a2213ead-91cc-5713-a2cc-ae82b1d361ca","userId":"6e8a95c3-3bea-5121-98e7-c96a68873b95","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='a2213ead-91cc-5713-a2cc-ae82b1d361ca' AND c.user_id='6e8a95c3-3bea-5121-98e7-c96a68873b95' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='unique-distinct-scope-b' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='bd5f4afa-71f9-5734-836a-6a702e5d50d0' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"a2213ead-91cc-5713-a2cc-ae82b1d361ca","userId":"6e8a95c3-3bea-5121-98e7-c96a68873b95","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='210eec42-2ff1-5697-aca0-bbeb3c9fc665' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"6e8a95c3-3bea-5121-98e7-c96a68873b95","track":"customer","customerProfileId":"a2213ead-91cc-5713-a2cc-ae82b1d361ca","sourceCreationRevision":"0","sourceCreationReceipt":"73457ca4-16c9-5dbb-8d64-61869a0656a7","semanticKey":"customer_buyer_profile/a2213ead-91cc-5713-a2cc-ae82b1d361ca/default-free-enrollment/v1"}'::jsonb)))=2));
